'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import {
  getLiveHealth,
  getReadiness,
  getDemoActors,
  getDemoFixtures,
  createDemoSession,
  getCurrentSession,
  getTransactionEvidence,
  getDisputeEvidence,
  getDisputeCase,
  getConversations,
  getConversationThread,
  requestEscalation,
  decideEscalation,
  uploadAttachment,
} from '../../lib/backend';

interface TestResult {
  endpoint: string;
  timeMs: number;
  status: number;
  data: any;
  isError: boolean;
}

export default function PruebasPage() {
  const [results, setResults] = useState<Record<string, TestResult>>({});
  const [activeActorId, setActiveActorId] = useState('demo-customer-1');
  const [autoThreadId, setAutoThreadId] = useState('demo-thread-1');
  const [autoApprovalId, setAutoApprovalId] = useState('');
  const [autoCaseId, setAutoCaseId] = useState('demo-case-1');
  const [autoTransactionId, setAutoTransactionId] = useState('demo-transaction-1');
  const [autoDisputeId, setAutoDisputeId] = useState('demo-dispute-1');

  // Helper to execute and record endpoint calls
  const runTest = async (key: string, name: string, fn: () => Promise<any>) => {
    const start = performance.now();
    try {
      const res = await fn();
      const elapsed = Math.round(performance.now() - start);

      setResults((prev) => ({
        ...prev,
        [key]: {
          endpoint: name,
          timeMs: elapsed,
          status: res.status || (res.ok ? 200 : 500),
          data: res.ok ? res.data : res.problem || res,
          isError: !res.ok,
        },
      }));

      // Auto-fill IDs if present
      if (res.data?.approvalId) setAutoApprovalId(res.data.approvalId);
      if (res.data?.threadId) setAutoThreadId(res.data.threadId);
      if (res.data?.caseId) setAutoCaseId(res.data.caseId);
      if (res.data?.transactionId) setAutoTransactionId(res.data.transactionId);
      if (res.data?.disputeId) setAutoDisputeId(res.data.disputeId);
    } catch (err: any) {
      const elapsed = Math.round(performance.now() - start);
      setResults((prev) => ({
        ...prev,
        [key]: {
          endpoint: name,
          timeMs: elapsed,
          status: 500,
          data: { error: err.message || 'Excepción no capturada' },
          isError: true,
        },
      }));
    }
  };

  const renderCardResult = (key: string) => {
    const result = results[key];
    if (!result) return null;

    return (
      <div
        style={{
          marginTop: '0.8rem',
          backgroundColor: '#0E1A2B',
          borderRadius: '6px',
          padding: '0.75rem',
          fontFamily: 'monospace',
          fontSize: '0.78rem',
          color: result.isError ? '#FCE7E9' : '#D6DDE8',
          borderLeft: result.isError ? '4px solid var(--red-primary)' : '4px solid var(--green-primary)',
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.4rem', color: '#8CA3CB', fontWeight: 'bold' }}>
          <span>Estado HTTP: {result.status}</span>
          <span>Tiempo: {result.timeMs} ms</span>
        </div>
        <pre style={{ margin: 0, whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
          {JSON.stringify(result.data, null, 2)}
        </pre>
      </div>
    );
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', backgroundColor: 'var(--bg-color)' }}>
      {/* Header */}
      <header className="app-header">
        <div className="brand-title">
          <span>🧪 Consola de Pruebas Backend API</span>
        </div>
        <Link href="/" className="btn-secondary">
          ← Volver al Inicio
        </Link>
      </header>

      <main style={{ flex: 1, padding: '2rem 1.5rem', maxWidth: '1100px', width: '100%', margin: '0 auto' }}>
        <p style={{ fontSize: '0.95rem', color: 'var(--text-muted)', marginBottom: '1.5rem' }}>
          Ejecuta pruebas directas sobre los endpoints REST del backend corriendo en <code>http://localhost:3000</code>. Los IDs capturados se autocompletan para las pruebas encadenadas.
        </p>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
          {/* Section 1: Salud */}
          <div className="panel-card" style={{ padding: '1.25rem' }}>
            <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '0.5rem', color: 'var(--blue-primary)' }}>
              1. Salud del Proceso (/v1/health)
            </h3>
            <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: '0.8rem' }}>
              Verifica el estado de liveness y readiness del backend Fastify.
            </p>
            <div style={{ display: 'flex', gap: '0.6rem' }}>
              <button
                className="btn-primary"
                onClick={() => runTest('s1_live', 'GET /v1/health/live', getLiveHealth)}
                type="button"
              >
                Probar /v1/health/live
              </button>
              <button
                className="btn-secondary"
                onClick={() => runTest('s1_ready', 'GET /v1/health/ready', getReadiness)}
                type="button"
              >
                Probar /v1/health/ready
              </button>
            </div>
            {renderCardResult('s1_live')}
            {renderCardResult('s1_ready')}
          </div>

          {/* Section 2: Sesión de Demo */}
          <div className="panel-card" style={{ padding: '1.25rem' }}>
            <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '0.5rem', color: 'var(--blue-primary)' }}>
              2. Sesión Demo y Contexto (/v1/demo y /v1/me)
            </h3>
            <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: '0.8rem' }}>
              Consulta los alias demo, crea la cookie de sesión autenticada y confirma los roles y capacidades.
            </p>
            <div style={{ display: 'flex', gap: '0.6rem', flexWrap: 'wrap', alignItems: 'center' }}>
              <button
                className="btn-secondary"
                onClick={() => runTest('s2_actors', 'GET /v1/demo/actors', getDemoActors)}
                type="button"
              >
                Listar Actores Demo
              </button>
              <select
                className="select-actor"
                value={activeActorId}
                onChange={(e) => setActiveActorId(e.target.value)}
                style={{ height: '36px', border: '1px solid var(--line-color)', color: 'var(--text-ink)', backgroundColor: 'var(--bg-color)' }}
              >
                <option value="demo-customer-1">demo-customer-1 (Cliente)</option>
                <option value="demo-backoffice-1">demo-backoffice-1 (Operador)</option>
              </select>
              <button
                className="btn-primary"
                onClick={() => runTest('s2_sess', `POST /v1/demo/sessions (${activeActorId})`, () => createDemoSession(activeActorId))}
                type="button"
              >
                Crear Sesión Demo
              </button>
              <button
                className="btn-secondary"
                onClick={() => runTest('s2_me', 'GET /v1/me', getCurrentSession)}
                type="button"
              >
                Probar /v1/me
              </button>
            </div>
            {renderCardResult('s2_actors')}
            {renderCardResult('s2_sess')}
            {renderCardResult('s2_me')}
          </div>

          {/* Section 3: Evidencia Sintética */}
          <div className="panel-card" style={{ padding: '1.25rem' }}>
            <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '0.5rem', color: 'var(--blue-primary)' }}>
              3. Consulta de Evidencias (Fixtures, Transacciones, Disputas, Casos)
            </h3>
            <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: '0.8rem' }}>
              Obtén las fixtures demo e inspecciona la evidencia sintética de transacciones, disputas y casos.
            </p>
            <div style={{ display: 'flex', gap: '0.6rem', flexWrap: 'wrap' }}>
              <button
                className="btn-secondary"
                onClick={() => runTest('s3_fixtures', 'GET /v1/demo/fixtures', getDemoFixtures)}
                type="button"
              >
                Obtener Fixtures Demo
              </button>
              <button
                className="btn-primary"
                onClick={() => runTest('s3_tx', `GET /v1/transactions/${autoTransactionId}`, () => getTransactionEvidence(autoTransactionId))}
                type="button"
              >
                Evidencia Transacción ({autoTransactionId})
              </button>
              <button
                className="btn-secondary"
                onClick={() => runTest('s3_disp', `GET /v1/disputes/${autoDisputeId}`, () => getDisputeEvidence(autoDisputeId))}
                type="button"
              >
                Evidencia Disputa ({autoDisputeId})
              </button>
              <button
                className="btn-secondary"
                onClick={() => runTest('s3_case', `GET /v1/dispute-cases/${autoCaseId}`, () => getDisputeCase(autoCaseId))}
                type="button"
              >
                Evidencia Caso ({autoCaseId})
              </button>
            </div>
            {renderCardResult('s3_fixtures')}
            {renderCardResult('s3_tx')}
            {renderCardResult('s3_disp')}
            {renderCardResult('s3_case')}
          </div>

          {/* Section 4: Conversaciones */}
          <div className="panel-card" style={{ padding: '1.25rem' }}>
            <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '0.5rem', color: 'var(--blue-primary)' }}>
              4. Gestión de Conversaciones (/v1/conversations)
            </h3>
            <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: '0.8rem' }}>
              Lista los snapshots de conversaciones autorizadas y consulta un hilo específico por threadId.
            </p>
            <div style={{ display: 'flex', gap: '0.6rem', alignItems: 'center' }}>
              <button
                className="btn-primary"
                onClick={() => runTest('s4_list', 'GET /v1/conversations', getConversations)}
                type="button"
              >
                Listar Conversaciones
              </button>
              <input
                type="text"
                placeholder="threadId..."
                value={autoThreadId}
                onChange={(e) => setAutoThreadId(e.target.value)}
                style={{ padding: '0.45rem 0.6rem', border: '1px solid var(--line-color)', borderRadius: 'var(--control-radius)', fontSize: '0.85rem' }}
              />
              <button
                className="btn-secondary"
                onClick={() => runTest('s4_thread', `GET /v1/conversations/${autoThreadId}`, () => getConversationThread(autoThreadId))}
                type="button"
              >
                Consultar Hilo
              </button>
            </div>
            {renderCardResult('s4_list')}
            {renderCardResult('s4_thread')}
          </div>

          {/* Section 5: Escalación y Aprobación */}
          <div className="panel-card" style={{ padding: '1.25rem' }}>
            <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '0.5rem', color: 'var(--blue-primary)' }}>
              5. Escalación y Aprobación de Disputas (Acciones Invasivas)
            </h3>
            <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: '0.8rem' }}>
              Solicita el escalamiento mock (crea un approvalId) y toma la decisión como operador (approved/rejected).
            </p>
            <div style={{ display: 'flex', gap: '0.6rem', flexWrap: 'wrap', alignItems: 'center' }}>
              <button
                className="btn-primary"
                onClick={() => runTest('s5_esc', `POST /v1/dispute-cases/${autoCaseId}/escalations`, () => requestEscalation(autoCaseId))}
                type="button"
              >
                Solicitar Escalamiento (Caso {autoCaseId})
              </button>

              <input
                type="text"
                placeholder="approvalId..."
                value={autoApprovalId}
                onChange={(e) => setAutoApprovalId(e.target.value)}
                style={{ padding: '0.45rem 0.6rem', border: '1px solid var(--line-color)', borderRadius: 'var(--control-radius)', fontSize: '0.85rem', width: '250px' }}
              />

              <button
                className="btn-primary"
                onClick={() => runTest('s5_app', `POST /v1/approvals/${autoApprovalId}/decisions (approved)`, () => decideEscalation(autoApprovalId, 'approved'))}
                disabled={!autoApprovalId}
                type="button"
                style={{ backgroundColor: 'var(--green-primary)' }}
              >
                Aprobar (SÍ)
              </button>

              <button
                className="btn-secondary"
                onClick={() => runTest('s5_rej', `POST /v1/approvals/${autoApprovalId}/decisions (rejected)`, () => decideEscalation(autoApprovalId, 'rejected'))}
                disabled={!autoApprovalId}
                type="button"
                style={{ color: 'var(--red-primary)', borderColor: 'var(--red-primary)' }}
              >
                Rechazar (NO)
              </button>
            </div>
            {renderCardResult('s5_esc')}
            {renderCardResult('s5_app')}
            {renderCardResult('s5_rej')}
          </div>

          {/* Section 6: Adjuntos de Conversación */}
          <div className="panel-card" style={{ padding: '1.25rem' }}>
            <h3 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: '0.5rem', color: 'var(--blue-primary)' }}>
              6. Flujo de Subida de Adjuntos en 3 Pasos (/v1/uploads)
            </h3>
            <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: '0.8rem' }}>
              Ejecuta el ciclo de 3 pasos: 1) Solicitud de autorización, 2) Carga de bytes binary, 3) Marcado como ready.
            </p>
            <div style={{ display: 'flex', gap: '0.6rem', alignItems: 'center' }}>
              <button
                className="btn-primary"
                onClick={() => {
                  const dummyFile = new File(['123456789012'], 'recibo_test.png', { type: 'image/png' });
                  runTest('s6_up', 'Flujo de Adjunto 3 Pasos', () => uploadAttachment(dummyFile, 'image'));
                }}
                type="button"
              >
                Subir Adjunto Imagen Sintético (12 bytes)
              </button>
            </div>
            {renderCardResult('s6_up')}
          </div>
        </div>
      </main>
    </div>
  );
}
